DROP TABLE IF EXISTS data.training_points CASCADE;
CREATE TABLE data.training_points (
  id               bigserial PRIMARY KEY,
  geom             geometry(Point, 4326) NOT NULL,
  mese             smallint,
  giorno_settimana text,
  fascia_oraria    text,
  comune           text,
  nome_strada      text,
  tipo_luogo       text,
  kmt_etm          real,
  fondo            text,
  segnaletica      text,
  meteo            text,
  incidente        smallint NOT NULL,
  esito            text NOT NULL
);


CREATE INDEX training_geom_gist   ON data.training_points USING GIST (geom);
CREATE INDEX training_esito_idx   ON data.training_points (esito);
CREATE INDEX training_comune_idx  ON data.training_points (comune);

